document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("home-news");if(!n)return;const e=ForjaStorage.getNoticias();0!==e.length?e.slice().reverse().slice(0,3).forEach(e=>{n.innerHTML+=`\n\n\n<article class="news-card">\n\n\n\n<img \nsrc="${e.imagem||"assets/img/logo.png"}"\nalt="${e.titulo}"\n>\n\n\n\n<div>\n\n\n<h3>\n${e.titulo}\n</h3>\n\n\n\n<p>\n${e.conteudo.substring(0,120)}...\n</p>\n\n\n\n<span>\n\n${e.data}\n\n</span>\n\n\n\n</div>\n\n\n\n</article>\n\n\n\n`}):n.innerHTML="\n\n<p>\nNenhuma notícia disponível.\n</p>\n\n"});